use cw_render::{Renderer,RenderStats};use cw_scene::*;
fn fixture()->Scene{let mut s=Scene::new(1280,720);for i in 0..100{let x=(i%4)*320;let y=(i/4)*22;s.nodes.push(Node::text(i as u64,Rect::new(x,y,320,22),format!("Computer row {i:03}"),16,Color::BLACK));}s}
fn main(){let mut result=vec![];for percent in [0,1,10,100]{let mut r=Renderer::new();let mut s=fixture();r.render(&s);r.stats=RenderStats::default();let start=std::time::Instant::now();for i in 0..300{if percent==0{r.render_ref(&s);}else{let operations=(0..percent).map(|n|{let mut node=s.nodes[n].clone();node.primitive=Primitive::Text{text:format!("Version {i:05}"),color:Color::BLACK,size:16};PatchOp::Upsert(node)}).collect();let d=s.patch(ScenePatch{base_revision:s.revision,revision:s.revision+1,operations}).unwrap();r.render_incremental(&s,&d);}}result.push(serde_json::json!({"percent":percent,"iterations":300,"wall_ns":start.elapsed().as_nanos(),"stages":r.stats}));}println!("{}",serde_json::to_string_pretty(&result).unwrap());}
